CREATE OR REPLACE FUNCTION public.gerball_forward_outcomes()\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''\nAS $function$\nWITH rules AS (\n SELECT version,evaluation_start,frozen_at FROM gerball_tracking_private.rule_versions\n WHERE version='ppg_last5_dates_050_v1'\n), leagues AS (\n SELECT key AS league_code FROM rules r CROSS JOIN LATERAL jsonb_object_keys((SELECT specification->'leagues' FROM gerball_tracking_private.rule_versions WHERE version=r.version)) AS key\n), reps AS MATERIALIZED (\n SELECT DISTINCT q.representative_id,q.league_code,q.market\n FROM gerball_tracking_private.qualified_representatives q\n JOIN rules r ON q.rule_version=r.version\n), evidence AS (\n SELECT r.league_code,r.market,o.phase,o.id AS observation_id,o.recorded_at,o.kickoff_at,\n COALESCE(s.status,'pending') result_status,s.full_time_result\n FROM reps r JOIN gerball_tracking_private.observations o ON o.id=r.representative_id\n LEFT JOIN LATERAL (\n  SELECT status,full_time_result FROM gerball_tracking_private.result_revisions\n  WHERE observation_id=o.id ORDER BY revision DESC LIMIT 1\n ) s ON true\n), combos AS (\n SELECT l.league_code,m.market,p.phase FROM leagues l\n CROSS JOIN (VALUES ('H'),('D'),('A')) m(market)\n CROSS JOIN (VALUES ('calibration'),('post_boundary')) p(phase)\n), metrics AS (\n SELECT c.league_code,c.market,c.phase,\n count(e.observation_id)::integer AS qualified,\n count(e.observation_id) FILTER (WHERE e.result_status='settled')::integer AS settled,\n count(e.observation_id) FILTER (WHERE e.result_status='settled' AND e.full_time_result=c.market)::integer AS matched,\n count(e.observation_id) FILTER (WHERE e.result_status='pending')::integer AS pending,\n count(e.observation_id) FILTER (WHERE e.result_status='review')::integer AS review\n FROM combos c LEFT JOIN evidence e ON e.league_code=c.league_code AND e.market=c.market AND e.phase=c.phase\n GROUP BY c.league_code,c.market,c.phase\n), overall AS (\n SELECT market,phase,sum(qualified)::integer qualified,sum(settled)::integer settled,\n sum(matched)::integer matched,sum(pending)::integer pending,sum(review)::integer review\n FROM metrics GROUP BY market,phase\n)\nSELECT jsonb_build_object(\n 'version','forward_outcomes_v1',\n 'generated_at',now(),\n 'rule_version',(SELECT version FROM rules),\n 'rule_frozen_at',(SELECT frozen_at FROM rules),\n 'evaluation_start',(SELECT evaluation_start FROM rules),\n 'basis','first qualifying representative per event and market; each league counted once',\n 'pricing_status','unpriced historical rule observations only; no approved priced strategy, stake or ROI',\n 'summary',(SELECT jsonb_agg(jsonb_build_object('market',market,'phase',phase,'qualifying',qualified,\n 'settled',settled,'matched',matched,'not_matched',settled-matched,\n 'pending',pending,'review',review,'match_rate_pct',CASE WHEN settled>0 THEN round(100.0*matched/settled,2) ELSE NULL END)\n ORDER BY phase,market) FROM overall),\n 'leagues',(SELECT jsonb_agg(jsonb_build_object('league',league_code,'market',market,'phase',phase,\n 'qualifying',qualified,'settled',settled,'matched',matched,\n 'pending',pending,'review',review) ORDER BY league_code,phase,market) FROM metrics),\n 'total_unique_market_observations',(SELECT count(*) FROM evidence),\n 'capture_dates',(SELECT count(DISTINCT capture_date) FROM gerball_tracking_private.cohorts)\n)\n$function$\n\nREVOKE ALL ON FUNCTION public.gerball_forward_outcomes() FROM PUBLIC,anon,authenticated;\nGRANT EXECUTE ON FUNCTION public.gerball_forward_outcomes() TO service_role;\nNOTIFY pgrst,'reload schema';\n